using ZosyalMedya.BuildingBlocks.Domain;using ZosyalMedya.Modules.Communities.Domain.Communities;using Xunit;
namespace ZosyalMedya.Tests.Unit.Communities;public sealed class CommunityDomainTests{[Fact]public void RolesMembershipRulesAndArchiveProtectInvariants(){var now=new DateTimeOffset(2026,7,12,17,0,0,TimeSpan.Zero);var owner=new CommunityActorId(Guid.NewGuid());var candidate=new CommunityActorId(Guid.NewGuid());var community=Community.Create(CommunityId.New(),owner,"mimari-ekibi","Mimari Ekibi","Birlikte öğrenme",CommunityVisibility.Private,now);community.RequestMembership(candidate,now);Assert.Equal(MembershipStatus.Pending,community.Members.Single(x=>x.UserId==candidate).Status);Assert.Throws<DomainRuleException>(()=>community.SetRules(candidate,["Yetkisiz"],now));community.Approve(owner,candidate,now);community.SetRules(owner,["Saygılı ol","Kaynak göster"],now);community.Archive(owner,"Dönem sona erdi",now);Assert.Equal(CommunityStatus.Archived,community.Status);Assert.Throws<DomainRuleException>(()=>community.SetRules(owner,["Arşiv sonrası"],now));Assert.Throws<DomainRuleException>(()=>community.Pin(owner,Guid.NewGuid(),true,now));Assert.True(community.AuditHistory.Count>=4);}}
